        if lhs.fileSize != rhs.fileSize {
            return false
        }
        if lhs.length != rhs.length {
            return false
        }
        if lhs.lengthFormatted != rhs.lengthFormatted {
            return false
        }
        if lhs.dataFormat != rhs.dataFormat {
            return false
        }
        if lhs.codec != rhs.codec {
            return false
        }
        if lhs.sampleRate != rhs.sampleRate {
            return false
        }
        if lhs.channels != rhs.channels {
            return false
        }
        if lhs.bitsPerSample != rhs.bitsPerSample {
            return false
        }
        if lhs.lossless != rhs.lossless {
            return false
        }
        if lhs.channelMode != rhs.channelMode {
            return false
        }
        if lhs.bitrate != rhs.bitrate {
            return false
        }
        if lhs.compressionRatio != rhs.compressionRatio {
            return false
        }
        if lhs.fileFormat != rhs.fileFormat {
            return false
        }
        return true
